//
// Rigged cyclist (GLB generated by tools/blender/argus_rider/build_rider.py from
// MakeHuman CC0 assets) posed on the bike every frame by inverse kinematics:
//
//   torso   pelvis tilt + spine flexion solved once per bike fit so the arms reach the
//           hoods with a natural elbow bend; hips placed over the saddle socket
//   legs    2-bone IK (thigh, calf) to the ankle, the foot then swings so the ball of
//           the foot sits on the pedal; the ankle angle follows the crank (ankling)
//   arms    2-bone IK to the wrists behind the hoods, elbows out and slightly bent,
//           hands rotated onto the hoods
//   head    neck and head extended so the rider looks up the road
//
// All the maths runs in the glTF root's own space ("model space": right-handed, no
// reflection; Babylon's handedness flip lives in the __root__ node only), with forward
// kinematics computed from the bones' local TRS. Contact points arrive in rider-body
// space (+z forward, +y up, +x right) and are converted.

import { TransformNode, Vector3, Matrix, Quaternion, Color3 } from './babylon.js';
import { instantiate } from './ModelCache.js';
import riderUrl from '../../assets/scene3d/models/argus_rider.glb?url';

const BONES = [
    'Root', 'pelvis', 'spine_01', 'spine_02', 'spine_03', 'neck_01', 'head',
    'clavicle_l', 'upperarm_l', 'lowerarm_l', 'hand_l', 'middle_01_l',
    'clavicle_r', 'upperarm_r', 'lowerarm_r', 'hand_r', 'middle_01_r',
    'thigh_l', 'calf_l', 'foot_l', 'ball_l', 'thigh_r', 'calf_r', 'foot_r', 'ball_r'
];
const SPINE_SPLIT = { pelvis: 0.38, spine_01: 0.22, spine_02: 0.22, spine_03: 0.18 };
const ARM_REACH = 0.94;     // shoulder→wrist distance / straight-arm length
const HIP_ABOVE_SADDLE = 0.088;
const LOOK_UP = 0.42;       // rad of neck+head extension relative to the torso lean

export class RiderModel {
    /**
     * @param {Scene} scene
     * @param {TransformNode} parent rider-body node
     * @param {{name?: string, alpha?: number}} opts
     * @returns {Promise<RiderModel>}
     */
    static async create(scene, parent, { name = 'rider', alpha = 1 } = {}) {
        const entries = await instantiate(scene, riderUrl, `${name}-body`, alpha < 1);
        return new RiderModel(scene, parent, entries, { name: `${name}-body`, alpha });
    }

    constructor(scene, parent, entries, { name, alpha }) {
        this.scene = scene;
        // body → offset (hip placement) → glTF __root__ (handedness flip) → bones
        this.offset = new TransformNode(`${name}-offset`, scene);
        this.offset.parent = parent;
        this.root = entries.rootNodes[0];
        this.root.parent = this.offset;
        this.parent = parent;
        const all = this.root.getDescendants(false);
        const byName = new Map(all.map((n) => [n.name.slice(n.name.indexOf(':') + 1), n]));
        this.b = {};
        for (const n of BONES) {
            const node = byName.get(n);
            if (!node) throw new Error(`rider model: bone "${n}" missing`);
            node.rotationQuaternion = node.rotationQuaternion || Quaternion.FromEulerVector(node.rotation);
            this.b[n] = node;
        }
        // Every skeleton-driven node, parents before children (for forward kinematics).
        this.nodes = all.filter((n) => n.getClassName() === 'TransformNode' && !n.getTotalVertices).sort((a, c) => depth(a) - depth(c));
        this.rest = new Map(this.nodes.map((n) => [n, n.rotationQuaternion ? n.rotationQuaternion.clone() : null]));
        this.rel = new Map(this.nodes.map((n) => [n, new Matrix()]));
        this.meshes = this.root.getChildMeshes(false).filter((m) => m.getTotalVertices() > 0);
        for (const m of this.meshes) {
            m.isPickable = false;
            m.receiveShadows = true;
            m.alwaysSelectAsActiveMesh = true; // skinned: bounds do not follow the pose
        }
        if (alpha < 1) this._makeGhost(alpha);
        this._m = [new Matrix(), new Matrix(), new Matrix(), new Matrix()];
        this._q = new Quaternion();
        this._axisSign = this._rotationSign();
        this._measureRest();
        this.torso = null;   // solved pose per bike fit
    }

    _makeGhost(alpha) {
        const seen = new Set();
        for (const m of this.meshes) {
            const mat = m.material;
            if (!mat || seen.has(mat)) continue;
            seen.add(mat);
            mat.alpha = alpha;
            mat.transparencyMode = 2;
            if (mat.emissiveColor) mat.emissiveColor = new Color3(0.0, 0.35, 0.45);
        }
    }

    // ------------------------------------------------------------------
    // Spaces and forward kinematics
    // ------------------------------------------------------------------

    /** Body-space point → model space (through offset and the glTF root). */
    toModel(p, out = new Vector3()) {
        this.offset.computeWorldMatrix(true);
        this.root.computeWorldMatrix(true);
        // model = p · inv(rootLocal · offsetLocal) (row vectors; body is the parent).
        const m = this._m[0];
        this.root.getWorldMatrix().multiplyToRef(Matrix.Invert(this.parent.getWorldMatrix()), m);
        m.invert();
        return Vector3.TransformCoordinatesToRef(p, m, out);
    }

    _fk() {
        const m = this._m[1];
        for (const n of this.nodes) {
            Matrix.ComposeToRef(n.scaling, n.rotationQuaternion || Quaternion.Identity(), n.position, m);
            const rel = this.rel.get(n);
            const parentRel = this.rel.get(n.parent);
            if (parentRel) m.multiplyToRef(parentRel, rel);
            else rel.copyFrom(m);
        }
    }

    pos(name, out = new Vector3()) {
        return this.rel.get(this.b[name]).getTranslationToRef(out);
    }

    _rotationSign() {
        // Matrix.RotationAxis sense in row-vector convention: +90° about z maps x → ±y.
        const m = Matrix.RotationAxis(new Vector3(0, 0, 1), Math.PI / 2);
        return Vector3.TransformNormal(new Vector3(1, 0, 0), m).y > 0 ? 1 : -1;
    }

    /** Model-space rotation W (row-vector matrix) taking direction u to v. */
    _swingMatrix(u, v, out) {
        const a = u.normalizeToNew(), b = v.normalizeToNew();
        const axis = Vector3.Cross(a, b);
        const s = axis.length();
        const angle = Math.atan2(s, Vector3.Dot(a, b));
        if (s < 1e-8) return Matrix.IdentityToRef(out);
        axis.scaleInPlace(1 / s);
        return Matrix.RotationAxisToRef(axis, this._axisSign * angle, out);
    }

    /** Applies a model-space rotation to a bone (keeps its joint position), then FK. */
    _applyRel(node, W, fk = true) {
        // (multiplyToRef must not write into one of its operands.)
        const rel = this.rel.get(node);
        const parentRel = this.rel.get(node.parent);
        const rot = this._m[2], tmp = this._m[3], inv = this._m[0];
        rel.getRotationMatrixToRef(rot);
        rot.multiplyToRef(W, tmp);               // new model-space rotation
        if (parentRel) {
            parentRel.getRotationMatrixToRef(inv);
            inv.transposeToRef(rot);             // inverse of a rotation
            tmp.multiplyToRef(rot, inv);         // local = model · inv(parent model)
            Quaternion.FromRotationMatrixToRef(inv, node.rotationQuaternion);
        } else {
            Quaternion.FromRotationMatrixToRef(tmp, node.rotationQuaternion);
        }
        if (fk) this._fk();
    }

    /** Rotates `bone` about its joint so that joint `child` points at `target`. */
    _aim(bone, child, target) {
        const j = this.pos(bone), c = this.pos(child);
        const W = this._swingMatrix(c.subtract(j), target.subtract(j), new Matrix());
        this._applyRel(this.b[bone], W);
    }

    _rotateAbout(bone, axis, angle) {
        const W = Matrix.RotationAxis(axis, this._axisSign * angle);
        this._applyRel(this.b[bone], W);
    }

    _resetPose() {
        for (const [n, q] of this.rest) if (q) n.rotationQuaternion.copyFrom(q);
    }

    _measureRest() {
        this._resetPose();
        this._fk();
        const d = (a, c) => Vector3.Distance(this.pos(a), this.pos(c));
        this.len = {
            thigh: d('thigh_r', 'calf_r'), shin: d('calf_r', 'foot_r'),
            upper: d('upperarm_r', 'lowerarm_r'), fore: d('lowerarm_r', 'hand_r')
        };
        // Model-space frame: forward and right of the rider (MakeHuman faces +z in glTF).
        this.fwd = new Vector3(0, 0, 1);
        this.up = new Vector3(0, 1, 0);
        this.lateral = new Vector3(1, 0, 0); // rider's left (glTF +x = Blender +x = left side)
        // Foot geometry: ball of the foot relative to the ankle, in the rest pose.
        this.footVec = this.pos('ball_r').subtract(this.pos('foot_r'));
    }

    // ------------------------------------------------------------------
    // Fit
    // ------------------------------------------------------------------

    /**
     * Solves the torso for a bike (contact points in body space). Called once per bike.
     * @param {{saddle: Vector3, hands: Vector3[]}} fit
     */
    setFit(fit) {
        this.fit = fit;
        // Wrist targets: behind and above the hood socket (palms on the hoods).
        this.wristBody = fit.hands.map((h) => h.add(new Vector3(0, 0.03, -0.075)));
        const hipBody = fit.saddle.add(new Vector3(0, HIP_ABOVE_SADDLE, 0.02));
        const want = ARM_REACH * (this.len.upper + this.len.fore);
        let lo = 0.2, hi = 1.45, alpha = 0.8;
        for (let it = 0; it < 22; it++) {
            alpha = (lo + hi) / 2;
            this._poseTorso(alpha, hipBody);
            const wr = this.toModel(this.wristBody[1]);
            const dist = Vector3.Distance(this.pos('upperarm_r'), wr);
            // More lean → shoulders lower and further forward → closer to the hands.
            if (dist > want) lo = alpha; else hi = alpha;
        }
        this.torso = { alpha, hipBody, quats: new Map() };
        for (const n of ['pelvis', 'spine_01', 'spine_02', 'spine_03', 'neck_01', 'head']) {
            this.torso.quats.set(n, this.b[n].rotationQuaternion.clone());
        }
        this.torso.offset = this.offset.position.clone();
    }

    _poseTorso(alpha, hipBody) {
        this._resetPose();
        this.offset.position.setAll(0);
        this._fk();
        // Forward bend about the lateral axis, distributed along the spine.
        for (const [bone, k] of Object.entries(SPINE_SPLIT)) {
            this._rotateAbout(bone, this.lateral, alpha * k);
        }
        // Check the sense once: the neck must have moved forward.
        if (this._bendSign === undefined) {
            this._bendSign = Vector3.Dot(this.pos('neck_01').subtract(this.pos('pelvis')), this.fwd) > 0 ? 1 : -1;
            if (this._bendSign < 0) {
                this._resetPose();
                this._fk();
                this._lateralSign = -1;
                for (const [bone, k] of Object.entries(SPINE_SPLIT)) this._rotateAbout(bone, this.lateral.scale(-1), alpha * k);
            }
        } else if (this._bendSign < 0) {
            this._resetPose();
            this._fk();
            for (const [bone, k] of Object.entries(SPINE_SPLIT)) this._rotateAbout(bone, this.lateral.scale(-1), alpha * k);
        }
        // Look up the road: undo part of the lean in the neck and head.
        const lat = this.lateral.scale(this._bendSign < 0 ? -1 : 1);
        this._rotateAbout('neck_01', lat, -alpha * LOOK_UP * 0.5);
        this._rotateAbout('head', lat, -alpha * LOOK_UP * 0.5 - 0.12);
        // Hips over the saddle: move the offset so the hip joints' midpoint hits the target.
        const hips = this.pos('thigh_l').add(this.pos('thigh_r')).scale(0.5);
        const target = this.toModel(hipBody);
        const delta = target.subtract(hips);
        // Model-space direction → offset (body) space through the glTF root's local matrix.
        const rootLocal = this.root.computeWorldMatrix(true).multiply(Matrix.Invert(this.offset.computeWorldMatrix(true)));
        this.offset.position.addInPlace(Vector3.TransformNormal(delta, rootLocal));
        this._fk();
    }

    // ------------------------------------------------------------------
    // Per frame
    // ------------------------------------------------------------------

    /**
     * @param {(side: number, out: Vector3) => Vector3} pedalContact ball-of-foot contacts (body space)
     * @param {number} crank radians (0 = right crank forward)
     * @param {number} dt
     */
    update(pedalContact, crank) {
        if (!this.torso) return;
        this._resetPose();
        for (const [n, q] of this.torso.quats) this.b[n].rotationQuaternion.copyFrom(q);
        this.offset.position.copyFrom(this.torso.offset);
        // A little hip rock with the pedal stroke.
        this._fk();
        this._rotateAbout('pelvis', this.fwd, Math.sin(crank) * 0.035);
        for (const side of [1, -1]) this._leg(side, pedalContact, crank);
        for (const side of [1, -1]) this._arm(side);
    }

    _leg(side, pedalContact, crank) {
        const s = side > 0 ? 'r' : 'l';
        const ball = this.toModel(pedalContact(side, new Vector3()));
        ball.y += 0.012;                                     // sole thickness
        // Ankling: toes slightly down, more so through the bottom of the stroke.
        const a = crank + (side > 0 ? 0 : Math.PI);
        const pitch = -0.18 - 0.16 * Math.sin(a - 0.6);
        const fv = this.footVec.clone();
        const Rm = Matrix.RotationAxis(this.lateral, this._axisSign * pitch * (this._bendSign < 0 ? -1 : 1));
        const ankle = ball.subtract(Vector3.TransformNormal(fv, Rm));
        // Knee: 2-bone IK in the plane of the forward pole.
        const hip = this.pos(`thigh_${s}`);
        const L1 = this.len.thigh, L2 = this.len.shin;
        const d = ankle.subtract(hip);
        const dist = Math.min(L1 + L2 - 1e-4, Math.max(Math.abs(L1 - L2) + 1e-4, d.length()));
        const dirN = d.normalizeToNew();
        const pole = this.fwd.add(this.lateral.scale(side > 0 ? -0.08 : 0.08)).add(this.up.scale(0.2));
        const perp = pole.subtract(dirN.scale(Vector3.Dot(pole, dirN))).normalize();
        const a1 = (L1 * L1 - L2 * L2 + dist * dist) / (2 * dist);
        const h = Math.sqrt(Math.max(0, L1 * L1 - a1 * a1));
        const knee = hip.add(dirN.scale(a1)).add(perp.scale(h));
        this._aim(`thigh_${s}`, `calf_${s}`, knee);
        this._aim(`calf_${s}`, `foot_${s}`, hip.add(dirN.scale(dist)));
        this._aim(`foot_${s}`, `ball_${s}`, ball);
    }

    _arm(side) {
        const s = side > 0 ? 'r' : 'l';
        const i = side > 0 ? 1 : 0;
        const wrist = this.toModel(this.wristBody[i]);
        const sh = this.pos(`upperarm_${s}`);
        const L1 = this.len.upper, L2 = this.len.fore;
        const d = wrist.subtract(sh);
        const dist = Math.min(L1 + L2 - 1e-4, Math.max(Math.abs(L1 - L2) + 1e-4, d.length()));
        const dirN = d.normalizeToNew();
        // Elbows out (away from the body) and a little down/back.
        const out = this.lateral.scale(side > 0 ? -1 : 1);
        const pole = out.scale(0.75).add(this.up.scale(-0.55)).add(this.fwd.scale(-0.2));
        const perp = pole.subtract(dirN.scale(Vector3.Dot(pole, dirN))).normalize();
        const a1 = (L1 * L1 - L2 * L2 + dist * dist) / (2 * dist);
        const h = Math.sqrt(Math.max(0, L1 * L1 - a1 * a1));
        const elbow = sh.add(dirN.scale(a1)).add(perp.scale(h));
        this._aim(`upperarm_${s}`, `lowerarm_${s}`, elbow);
        this._aim(`lowerarm_${s}`, `hand_${s}`, sh.add(dirN.scale(dist)));
        // Hand onto the hood: knuckles ahead of and slightly below the wrist.
        const grip = this.toModel(this.fit.hands[i].add(new Vector3(0, -0.005, 0.03)));
        this._aim(`hand_${s}`, `middle_01_${s}`, grip);
    }

    setEnabled(on) {
        this.offset.setEnabled(on);
    }

    dispose() {
        this.offset.dispose(false, true);
    }
}

function depth(n) {
    let d = 0;
    for (let p = n.parent; p; p = p.parent) d++;
    return d;
}
